// One button, same control on several decks.

DJMT1.quantizeAll = function (ch, ctrl, value) {
    if (value === 0) {
        return;
    }
    var groups = ["[Channel1]", "[Channel2]"];
    var on = engine.getValue(groups[0], "quantize") ? 0 : 1;
    for (var i = 0; i < groups.length; i++) {
        engine.setValue(groups[i], "quantize", on);
    }
};

DJMT1.slipAll = function (ch, ctrl, value) {
    if (value === 0) {
        return;
    }
    var groups = ["[Channel1]", "[Channel2]"];
    var on = engine.getValue(groups[0], "slip_enabled") ? 0 : 1;
    for (var i = 0; i < groups.length; i++) {
        engine.setValue(groups[i], "slip_enabled", on);
    }
};

// Buttons whose value means something other than 'pressed'.

DJMT1.cloneFromB = function (ch, ctrl, value) {
    if (value === 0) {
        return;
    }
    engine.setValue("[Channel1]", "CloneFromDeck", 2);
};

DJMT1.cloneFromA = function (ch, ctrl, value) {
    if (value === 0) {
        return;
    }
    engine.setValue("[Channel2]", "CloneFromDeck", 1);
};

// BROWSE PUSH
DJMT1.browse_push = function (channel, control, value, status, group) {
    if (value !== 127) {
        return;   // release edge; act on the press only
    }
    engine.setValue("[Master]", "maximize_library",
        engine.getValue("[Master]", "maximize_library") ? 0 : 1);
};

// AUTO LOOP A
DJMT1.auto_loop_a = function (channel, control, value, status, group) {
    // A signed-relative encoder: 1 is one detent
    // clockwise, 127 one anticlockwise.
    var up = (value < 64);
    var v = engine.getValue("[Channel1]", "beatloop_size") || 8.0;
    v = up ? v * 2 : v / 2;
    v = Math.max(0.03125, Math.min(64, v));
    engine.setValue("[Channel1]", "beatloop_size", v);
};

// AUTO LOOP B
DJMT1.auto_loop_b = function (channel, control, value, status, group) {
    // A signed-relative encoder: 1 is one detent
    // clockwise, 127 one anticlockwise.
    var up = (value < 64);
    var v = engine.getValue("[Channel2]", "beatloop_size") || 8.0;
    v = up ? v * 2 : v / 2;
    v = Math.max(0.03125, Math.min(64, v));
    engine.setValue("[Channel2]", "beatloop_size", v);
};

// FX1 ON
DJMT1.fx1_on_shift = function (channel, control, value, status, group) {
    if (value !== 127) {
        return;   // release edge; act on the press only
    }
    engine.setValue("[EffectRack1_EffectUnit1]", "enabled",
        engine.getValue("[EffectRack1_EffectUnit1]", "enabled") ? 0 : 1);
};

// FX2 On
DJMT1.fx2_on_shift = function (channel, control, value, status, group) {
    if (value !== 127) {
        return;   // release edge; act on the press only
    }
    engine.setValue("[EffectRack1_EffectUnit2]", "enabled",
        engine.getValue("[EffectRack1_EffectUnit2]", "enabled") ? 0 : 1);
};
